# Now, for each song in todo_songs, let's search Spotify using the "search_songs" API with a query combining the title and artists.
# We'll collect the release date (month/year) for each song.
release_info = []

for song in todo_songs:
    query = f"{song['title']} {song['artists']}"
    # Get the first page of results, limit to 1 for best match
    result = apis.spotify.search_songs(query=query, page_limit=1)
    # Parse the release date from the first result, if available
    if result and isinstance(result, list) and len(result) > 0:
        song_data = result[0]
        # Try to get release date from song or album
        release_date = song_data.get("release_date") or song_data.get("album_release_date")
        if not release_date and "album" in song_data and isinstance(song_data["album"], dict):
            release_date = song_data["album"].get("release_date")
        release_info.append({
            "title": song["title"],
            "artists": song["artists"],
            "release_date": release_date
        })
    else:
        release_info.append({
            "title": song["title"],
            "artists": song["artists"],
            "release_date": None
        })

print(release_info)

